CREATE TABLE users (id uuid PRIMARY KEY, role text NOT NULL CHECK (role IN ('owner','admin','judge','participant')), contact text UNIQUE NOT NULL, name text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE editions (id uuid PRIMARY KEY, label text NOT NULL UNIQUE, state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','open','closed','archived')), registration_opens timestamptz, registration_closes timestamptz, event_date timestamptz, config jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE schools (id uuid PRIMARY KEY, reference text NOT NULL UNIQUE, name text NOT NULL, address text NOT NULL, city text NOT NULL, state text NOT NULL, postal_code text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','inactive')), registered_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), trashed_at timestamptz, deletion_batch_id uuid, purging boolean NOT NULL DEFAULT false);
CREATE TABLE school_contacts (id uuid PRIMARY KEY,school_id uuid NOT NULL REFERENCES schools(id),user_id uuid REFERENCES users(id),name text NOT NULL,role text NOT NULL,email text NOT NULL,phone text NOT NULL,verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE school_nominations (id uuid PRIMARY KEY,reference text UNIQUE NOT NULL,name text NOT NULL,city text NOT NULL,state text NOT NULL,address text NOT NULL DEFAULT '',nominator_contact text NOT NULL,school_contact text,status text NOT NULL DEFAULT 'pending',matched_school_id uuid REFERENCES schools(id),review_note text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE school_participations (id uuid PRIMARY KEY,school_id uuid NOT NULL REFERENCES schools(id),edition_id uuid NOT NULL REFERENCES editions(id),snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),trashed_at timestamptz,deletion_batch_id uuid,UNIQUE(school_id,edition_id));
CREATE TABLE students (id uuid PRIMARY KEY,reference text NOT NULL UNIQUE,name text NOT NULL,guardian_contact text NOT NULL,emergency_contact text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),trashed_at timestamptz,deletion_batch_id uuid,purging boolean NOT NULL DEFAULT false);
CREATE TABLE participant_access (user_id uuid NOT NULL REFERENCES users(id),student_id uuid NOT NULL REFERENCES students(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,student_id));
CREATE TABLE student_participations (id uuid PRIMARY KEY,student_id uuid NOT NULL REFERENCES students(id),school_id uuid NOT NULL REFERENCES schools(id),edition_id uuid NOT NULL REFERENCES editions(id),class integer NOT NULL CHECK(class BETWEEN 1 AND 12),section text NOT NULL DEFAULT '',coordinator text NOT NULL DEFAULT '',snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),trashed_at timestamptz,deletion_batch_id uuid,UNIQUE(student_id,edition_id));
CREATE TABLE consents (id uuid PRIMARY KEY,student_id uuid NOT NULL REFERENCES students(id),edition_id uuid NOT NULL REFERENCES editions(id),actor_id uuid NOT NULL REFERENCES users(id),purpose text NOT NULL,wording_version text NOT NULL,wording text NOT NULL,accepted boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE competitions (id uuid PRIMARY KEY,edition_id uuid NOT NULL REFERENCES editions(id),slug text NOT NULL,title text NOT NULL,guidelines text NOT NULL,version integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','closed')),opens_at timestamptz NOT NULL,closes_at timestamptz NOT NULL,config jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(edition_id,slug,version),CHECK(closes_at>opens_at));
CREATE TABLE submissions (id uuid PRIMARY KEY,reference text NOT NULL UNIQUE,student_participation_id uuid NOT NULL REFERENCES student_participations(id),competition_id uuid NOT NULL REFERENCES competitions(id),category_id text NOT NULL,state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','submitted','longlisted','disqualified','shortlisted','not_selected','finalized')),revision integer NOT NULL DEFAULT 0,answers jsonb NOT NULL DEFAULT '{}',lock_version integer NOT NULL DEFAULT 0,submitted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),trashed_at timestamptz,deletion_batch_id uuid,purging boolean NOT NULL DEFAULT false);
CREATE TABLE submission_members (submission_id uuid NOT NULL REFERENCES submissions(id),participation_id uuid NOT NULL REFERENCES student_participations(id),PRIMARY KEY(submission_id,participation_id));
CREATE TABLE submission_revisions (id uuid PRIMARY KEY,submission_id uuid NOT NULL REFERENCES submissions(id),version integer NOT NULL,answers jsonb NOT NULL,context jsonb NOT NULL,asset_ids jsonb NOT NULL,config jsonb NOT NULL,submitted_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(submission_id,version));
CREATE TABLE review_rounds (id uuid PRIMARY KEY,competition_id uuid NOT NULL REFERENCES competitions(id),name text NOT NULL,kind text NOT NULL CHECK(kind IN ('screening','scoring','jury')),eligible_states jsonb NOT NULL,open boolean NOT NULL DEFAULT false,rubric jsonb NOT NULL,rubric_version integer NOT NULL DEFAULT 1,decision_roles jsonb NOT NULL DEFAULT '["admin","owner"]',required_reviews integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assignment_rules (id uuid PRIMARY KEY,competition_id uuid NOT NULL REFERENCES competitions(id),category_id text NOT NULL,round_id uuid NOT NULL REFERENCES review_rounds(id),judge_id uuid NOT NULL REFERENCES users(id),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(competition_id,category_id,round_id,judge_id));
CREATE TABLE judge_assignments (id uuid PRIMARY KEY,submission_id uuid NOT NULL REFERENCES submissions(id),judge_id uuid NOT NULL REFERENCES users(id),round_id uuid NOT NULL REFERENCES review_rounds(id),rule_id uuid REFERENCES assignment_rules(id),revision integer NOT NULL,active boolean NOT NULL DEFAULT true,revoked_at timestamptz,revocation_reason text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(submission_id,judge_id,round_id));
CREATE TABLE reviews (id uuid PRIMARY KEY,assignment_id uuid NOT NULL REFERENCES judge_assignments(id),revision integer NOT NULL,rubric_version integer NOT NULL,scores jsonb NOT NULL DEFAULT '{}',comment text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted')),flag text,eligible_for_results boolean NOT NULL DEFAULT true,lock_version integer NOT NULL DEFAULT 0,submitted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(assignment_id,revision));
CREATE TABLE review_history (id uuid PRIMARY KEY,review_id uuid NOT NULL REFERENCES reviews(id),snapshot jsonb NOT NULL,reason text NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE decisions (id uuid PRIMARY KEY,submission_id uuid NOT NULL REFERENCES submissions(id),round_id uuid NOT NULL REFERENCES review_rounds(id),actor_id uuid NOT NULL REFERENCES users(id),from_state text NOT NULL,to_state text NOT NULL,reason text NOT NULL,jury_reference text,award text,revision integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE publications (id uuid PRIMARY KEY,submission_id uuid NOT NULL REFERENCES submissions(id),revision integer NOT NULL,title text NOT NULL,summary text NOT NULL,award text,approved_by uuid NOT NULL REFERENCES users(id),active boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(submission_id,revision));
CREATE TABLE deletion_batches (id uuid PRIMARY KEY,actor_id uuid NOT NULL REFERENCES users(id),reason text NOT NULL,root_type text NOT NULL,root_id uuid NOT NULL,items jsonb NOT NULL,status text NOT NULL DEFAULT 'trashed',created_at timestamptz NOT NULL DEFAULT now(),restored_at timestamptz);
CREATE TABLE audit_events (id uuid PRIMARY KEY,actor_id uuid,action text NOT NULL,entity_type text NOT NULL,entity_id text NOT NULL,detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs (id uuid PRIMARY KEY,kind text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,run_after timestamptz NOT NULL DEFAULT now(),locked_at timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE purge_ledger (id uuid PRIMARY KEY,entity_type text NOT NULL,entity_id uuid NOT NULL,storage_keys jsonb NOT NULL DEFAULT '[]',completed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE import_rows (id uuid PRIMARY KEY,source text NOT NULL,source_id text NOT NULL,kind text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending',entity_id uuid,error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source,source_id,kind));
CREATE TABLE site_content (key text PRIMARY KEY,title text NOT NULL,body text NOT NULL,approved boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX school_search ON schools(lower(name),lower(city));
CREATE INDEX student_search ON students(lower(name));
CREATE INDEX participations_edition ON student_participations(edition_id,school_id,class);
CREATE INDEX submission_filters ON submissions(competition_id,category_id,state,trashed_at);
CREATE INDEX submission_participant ON submissions(student_participation_id);
CREATE INDEX assignment_queue ON judge_assignments(judge_id,active,round_id);
CREATE INDEX job_queue ON jobs(status,run_after);
CREATE INDEX audit_lookup ON audit_events(entity_type,entity_id,created_at);
